{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — to maximize total profit (revenue minus raw material cost minus processing cost), or to maximize total revenue, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits or minimum production requirements for the three products, or can the factory produce and sell any quantity of each product as long as equipment hours are not exceeded?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of demand limits or minimum production requirements versus unlimited production within equipment constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the processing cost, is the cost per machine hour applied to the actual processing time consumed (i.e., cost = processing time per piece × number of pieces × rate per hour), so that the total processing cost for a product on a given equipment is the sum over all pieces of (time per piece × rate)?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of a specific cost calculation formula."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can the production quantities of the three products be fractional (i.e., is this a continuous linear program), or must each product be produced in whole units (integer quantities)?"
  ],
  "rationale": "The response asks a single clarification question regarding the variable type (continuous vs. integer) for the production quantities."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any requirement that each product's stage A and stage B processing must be done on the same equipment type, or can a product's stage A be done on one equipment and its stage B on a different one (e.g., Product I on A1 for stage A and B3 for stage B)?"
  ],
  "rationale": "The response asks a single clarification question regarding equipment constraints for processing stages, presented as a binary choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since a product can be split across multiple equipment types (e.g., some of Product I's stage A on A1 and some on A2), is it allowed to split a single product's production across different equipment types, or must all units of a given product on a given stage use exactly one equipment type?"
  ],
  "rationale": "The response asks for a single policy decision regarding whether production can be split across equipment types or must be consolidated to one type."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
